function getHeader(headers, name) {
  if (!Array.isArray(headers)) return "";
  const found = headers.find(h => String(h.name || "").toLowerCase() === String(name).toLowerCase());
  return found ? String(found.value || "") : "";
}

function parseAddress(value) {
  const raw = String(value || "").trim();
  if (!raw) return { email: "", name: "" };

  const match = raw.match(/^(.*)<([^>]+)>$/);
  if (match) {
    return {
      name: String(match[1] || "").trim().replace(/^"|"$/g, ""),
      email: String(match[2] || "").trim()
    };
  }

  return { name: "", email: raw };
}

function splitAddresses(value) {
  const raw = String(value || "").trim();
  if (!raw) return [];
  return raw.split(",").map(v => parseAddress(v).email).filter(Boolean);
}

function errorResult(code, message, source) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-GMAIL-INBOX",
      component_version: "v1",
      provider: "gmail",
      operation: "inbound_email_trigger",
      validation_status: "invalid",
      message_id: source.id || null,
      thread_id: source.threadId || null,
      from: { email: "", name: "" },
      to: [],
      cc: [],
      bcc: [],
      subject: null,
      snippet: source.snippet || "",
      body_text: source.snippet || "",
      received_at: source.internalDate || null,
      labels: source.labelIds || [],
      manual_review_required: true,
      error_code: code,
      error_message: message,
      next_action: "route_to_manual_review_or_error_log",
      status_log_event: "gmail_inbox_validation_error",
      downstream_components: ["C5-E", "C6-G", "C5-W"],
      source_result: source
    }
  }];
}

const source = $json.body && ($json.body.id || $json.body.threadId || $json.body.payload)
  ? $json.body
  : $json;

const headers = source.payload?.headers || source.headers || [];
const fromHeader = getHeader(headers, "From") || source.from || "";
const toHeader = getHeader(headers, "To") || source.to || "";
const ccHeader = getHeader(headers, "Cc") || source.cc || "";
const bccHeader = getHeader(headers, "Bcc") || source.bcc || "";
const subject = getHeader(headers, "Subject") || source.subject || "";
const dateHeader = getHeader(headers, "Date") || source.date || null;

if (!source.id) return errorResult("MISSING_MESSAGE_ID", "Gmail message id is required.", source);

const from = parseAddress(fromHeader);
if (!from.email) return errorResult("MISSING_FROM", "Gmail From header is required.", source);

const snippet = String(source.snippet || "");
const bodyText = String(source.body_text || source.text || snippet || "");

return [{
  json: {
    adapter_status: "success",
    component_id: "ADP-GMAIL-INBOX",
    component_version: "v1",
    provider: "gmail",
    operation: "inbound_email_trigger",
    validation_status: "valid",
    message_id: source.id,
    thread_id: source.threadId || null,
    from,
    to: splitAddresses(toHeader),
    cc: splitAddresses(ccHeader),
    bcc: splitAddresses(bccHeader),
    subject: subject || "",
    snippet,
    body_text: bodyText,
    received_at: dateHeader || source.internalDate || null,
    labels: source.labelIds || [],
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: "route_to_email_processing",
    status_log_event: "gmail_inbox_message_normalized",
    downstream_components: ["C4-B", "C4-A", "C2-D", "C2-B", "C5-W"],
    source_result: source
  }
}];

